// The plugin runtime: one cordis root context, three services every plugin can inject (ui,
// windows, plugins), and the hot-reload entry the native app calls when files under plugins/
// change. No layout here: the window manager is a plugin (provide: 'layout'); the runtime only
// keeps the registry of window types and hands tiles over to whichever layout runs.
//
// A plugin is plugins/<name>/index.js (built from src/plugins/<name>/index.ts), listed in
// plugins.json. Its default export is a cordis plugin (TilrPlugin in types.ts): an object
// { name, inject, apply(ctx) }, or a class (see plugins/counter). Everything a plugin does goes
// through ctx (ctx.effect, ctx.on, ctx.provide, ctx.ui.tile), so disposing its fiber undoes all
// of it — that is what makes swapping a plugin in place safe.
//
// Hot reload = import the new module (with a cache-busting query, the module map is keyed by
// URL), dispose the old fiber, start a new one. Plugins that inject a service the reloaded
// plugin provides are unloaded and reloaded by cordis itself.
//
// Versions: before a plugin starts, its `api` range is checked against the page's API version
// (`window.tilr.api`) and each `requires` range against the running provider's `version`; a
// mismatch leaves it unstarted, 'incompatible'. A provider starting re-checks the plugins that
// require its service (see `revalidate`).
//
// Limit: a plugin is one file. A module it imports relatively would stay cached across reloads.
// (Files it fetches, like a theme's CSS, are read fresh every start.)
import { bootPerformance, performanceCollector } from './performance.js'
import { Context, Service } from 'cordis'
import type { Fiber } from 'cordis'
import { adopt, mark, measure, metric, reactMode } from 'tilr'
import type { FiberStates, PluginHost as PluginHostApi, PluginModule, PluginRow, Popup, ServiceDescription, TilrGlobal, TilrPlugin, UI as UIApi, UIAction, UIActOptions, UISnapshotOptions, UISnapshotWindow, WindowHandle, Windows as WindowsApi, WindowType } from './types.ts'
// './lib.js', not './lib.ts': esbuild leaves import paths alone and the browser loads site/lib.js.
import { asError, hasDefault, injects, pluginNames, satisfies, stampBuild } from './lib.js'
import { drawControls, element, FRAME } from './dom.js'
import { Agent, closest, contractOf, describeElement, members, serviceProxy, shows } from './agent.js'
import type { Frame, Owner } from './agent.js'

const STORAGE_KEY = 'tilr-plugins-off'
// cordis' FiberState, by number.
const STATE: FiberStates = ['pending', 'loading', 'active', 'failed', 'disposed', 'unloading']

/** One plugin from plugins.json. `module` is the last file that imported; `fiber` is null while
 *  the plugin is off (or its file never imported, or it is incompatible). `incompatible`: the
 *  version check refused to start it, `error` says why. */
interface Entry {
  name: string
  module: PluginModule | null
  fiber: Fiber | null
  error: Error | null
  incompatible: boolean
  loadedAt: number | null
}

const root = new Context()
root.logger.exporter({
  export(message) {
    const log = console[message.type] ?? console.log
    log(`[${message.name}]`, ...message.args)
  },
})

/** A mounted window: the element its type draws into and the handle `mount` got. */
interface Mounted {
  type: string
  host: HTMLElement
  win: WindowHandle
}

/** How long after its mount a window is looked at for showing an agent nothing (its content
 *  may come in late: a fetch, a font). */
const BLIND_AFTER = 1000
/** The windows warned about as blind: once per window, across remounts. */
const blindWarned = new Set<string>()

/** `ctx.windows`: the registry of window types. A plugin registers how to draw a window of its
 *  type; the layout (a plugin, `provide: 'layout'`) opens, places and closes the windows. */
class Windows extends Service implements WindowsApi {
  declare scope: Context
  /** `owners`: type → the plugin that registered it (whose warning an unnamed control is).
   *  `mounted`: window id → where its type drew it (what the agent reads an adapter through). */
  declare state: { types: Map<string, WindowType>, owners: Map<string, string>, mounted: Map<string, Mounted> }

  constructor(ctx: Context) {
    super(ctx, 'windows')
    this.scope = ctx
    this.state = { types: new Map(), owners: new Map(), mounted: new Map() }
  }

  register<C>(type: string, definition: WindowType<C>): void {
    // this.ctx is the caller's context: the type leaves with the plugin that registered it.
    this.add(this.ctx, type, definition)
  }

  /** `register` on behalf of `ctx` (the ui service registers a tile's type for its caller). */
  add<C>(ctx: Context, type: string, definition: WindowType<C>): void {
    const { types, owners } = this.state
    if (types.has(type)) throw new Error(`window type "${type}" is already registered`)
    const owner = (ctx.root.get('plugins') as PluginHost | undefined)?.owner(ctx.fiber) ?? ctx.fiber.name
    if (performanceCollector) {
      const original = definition
      const mount: WindowType<C>['mount'] = (host, win) => {
        host.dataset.perfPlugin = owner ?? type
        host.dataset.perfWindow = win.id
        return original.mount(host, win)
      }
      definition = Object.create(original, { mount: { enumerable: true, value: mount } }) as WindowType<C>
    }
    // What the layout mounts: the definition (its prototype), its mount noting where the window
    // is drawn, for the agent (the window's adapter, its handle) and the blind-window check.
    const def = definition as WindowType
    const wrapped = Object.create(def, {
      mount: { enumerable: true, value: (host: HTMLElement, win: WindowHandle) => this.mount(type, def, host, win) },
    }) as WindowType
    ctx.effect(() => {
      types.set(type, wrapped)
      owners.set(type, owner)
      this.scope.emit('windows/change')
      return () => {
        types.delete(type)
        owners.delete(type)
        this.scope.emit('windows/change')
      }
    }, 'windows.register()')
  }

  /** The plugin that registered `type`, if it is registered. */
  owner(type: string): string | undefined {
    return this.state.owners.get(type)
  }

  /** Where the window `id` is drawn and its handle, while its type has it mounted. */
  mounted(id: string): Mounted | undefined {
    return this.state.mounted.get(id)
  }

  /** `definition.mount`, noted in `mounted` until its undo, and the blind-window check. */
  mount(type: string, definition: WindowType, host: HTMLElement, win: WindowHandle): () => void {
    const entry: Mounted = { type, host, win }
    this.state.mounted.set(win.id, entry)
    const unwatch = definition.agent?.text ? () => {} : this.watchBlind(type, host, win)
    const undo = definition.mount(host, win)
    return () => {
      unwatch()
      if (this.state.mounted.get(win.id) === entry) this.state.mounted.delete(win.id)
      if (undo) undo()
    }
  }

  /** A second after the mount: a window that shows nothing (no text, no control, no adapter
   *  text) is warned about once and counted in its plugin's a11y badge until content comes. */
  watchBlind(type: string, host: HTMLElement, win: WindowHandle): () => void {
    const plugins = () => this.scope.root.get('plugins') as PluginHost | undefined
    let counted: string | null = null
    let observer: MutationObserver | null = null
    const uncount = () => {
      if (counted !== null) plugins()?.blind(counted, -1)
      counted = null
    }
    const timer = setTimeout(() => {
      if (!host.isConnected || shows(host)) return
      const owner = this.owner(type) ?? type
      if (!blindWarned.has(win.id)) {
        blindWarned.add(win.id)
        console.warn(`[tilr] ${owner}: window "${win.title}" (${type}) shows nothing to agents: add agent.text to its WindowType`)
      }
      counted = owner
      plugins()?.blind(owner, 1)
      observer = new MutationObserver(() => {
        if (!shows(host)) return
        observer?.disconnect()
        uncount()
      })
      observer.observe(host, { subtree: true, childList: true, characterData: true, attributes: true })
    }, BLIND_AFTER)
    return () => {
      clearTimeout(timer)
      observer?.disconnect()
      uncount()
    }
  }

  get(type: string): WindowType | undefined {
    return this.state.types.get(type)
  }

  list(): string[] {
    return [...this.state.types.keys()]
  }
}

/** The elements marked with `ctx.ui.overlay()`, every plugin's: drawn over everything, the
 *  native web views included, which leave them to the page (the webviews service reads these).
 *  A size change of one (shown, hidden, resized) is told as `ui/overlay`. */
const overlays = new Set<HTMLElement>()
const overlaySizes = new ResizeObserver(() => root.emit('ui/overlay'))

/** `ctx.ui.tile({ title })` → the tile's body element; `ctx.ui.style(css)` → a stylesheet.
 *  Both leave with the plugin. Colors come from the theme's tokens (var(--accent) …).
 *  `overlay` and `popup`: what the page draws over everything, native web views included.
 *  `snapshot` and `act` are the agent's (agent.ts). */
class UI extends Service implements UIApi {
  /** The registry (the class: a caller's ctx reaches `windows` only if it injected it). */
  declare windows: Windows

  constructor(ctx: Context) {
    super(ctx, 'ui')
    this.windows = ctx.get('windows') as Windows
  }

  style(css: string): void {
    const sheet = new CSSStyleSheet()
    sheet.replaceSync(css)
    this.ctx.effect(() => adopt(document, sheet), 'ui.style()')
  }

  overlay(element: HTMLElement): () => void {
    let marked = false
    const unmark = () => {
      if (!marked) return
      marked = false
      overlays.delete(element)
      overlaySizes.unobserve(element)
      root.emit('ui/overlay')
    }
    // this.ctx is the caller's: the mark leaves with the plugin. Unmarked sooner, the effect
    // goes too (its disposer drops it from the plugin's), so a mark per menu opened adds up to nothing.
    const dispose = this.ctx.effect(() => {
      marked = true
      overlays.add(element)
      overlaySizes.observe(element)
      root.emit('ui/overlay')
      return unmark
    }, 'ui.overlay()')
    return () => { void dispose() }
  }

  overlays(): HTMLElement[] {
    return [...overlays]
  }

  popup(element: HTMLElement, { anchor }: { anchor?: HTMLElement } = {}): Popup {
    const listeners = new Set<(opened: boolean) => void>()
    let opened = false
    const set = (open: boolean) => {
      if (opened === open) return
      opened = open
      element.hidden = !open
      for (const listener of [...listeners]) listener(open)
    }
    element.hidden = true
    // A press outside the popup and its anchor, Escape, or the page losing the focus closes it.
    // composedPath: the popup and the anchor may sit in a shadow root.
    const outside = (event: Event) => {
      const path = event.composedPath()
      if (!path.includes(element) && !(anchor && path.includes(anchor))) set(false)
    }
    const escape = (event: KeyboardEvent) => { if (opened && event.key === 'Escape') set(false) }
    const blur = () => set(false)
    this.ctx.effect(() => {
      document.addEventListener('pointerdown', outside, true)
      document.addEventListener('keydown', escape, true)
      window.addEventListener('blur', blur)
      return () => {
        document.removeEventListener('pointerdown', outside, true)
        document.removeEventListener('keydown', escape, true)
        window.removeEventListener('blur', blur)
        set(false)
        listeners.clear()
      }
    }, 'ui.popup()')
    this.overlay(element)
    return {
      element,
      get opened() { return opened },
      open: () => set(true),
      close: () => set(false),
      toggle: () => set(!opened),
      subscribe(listener) {
        listeners.add(listener)
        return () => { listeners.delete(listener) }
      },
    }
  }

  /**
   * The tile is a `.tile` section (header, controls, body) the plugin owns. It is a window type
   * registered for this call alone (`<plugin>`, `<plugin>#2` …), opened on first use as a
   * singleton. Closing its window is remembered; reloading the plugin only remounts content.
   * Without a layout the tile is a plain grid cell.
   */
  tile({ title }: { title?: string } = {}): HTMLElement {
    // this.ctx is the caller's context: the effects belong to the plugin, not to the ui service.
    const ctx = this.ctx
    const grid = document.getElementById('grid') as HTMLElement // in index.html
    // The standard frame (dom.ts, what frame() and <Frame> draw too); the controls come with a layout.
    const tile = element('section', FRAME.tile)
    const header = element('header', undefined, title ?? ctx.fiber.name)
    header.setAttribute(FRAME.drag, '')
    const controls = element('div', FRAME.controls)
    const body = element('div', FRAME.body)
    tile.append(header, controls, body)
    // The type: the plugin's name in plugins.json (a class plugin's fiber is named after the
    // class), or the first free `name#n` (a plugin with several tiles).
    const host = ctx.root.get('plugins') as PluginHost | undefined
    const name = host?.owner(ctx.fiber) ?? ctx.fiber.name
    let type = name
    for (let n = 2; this.windows.get(type); n++) type = `${name}#${n}`
    // What the snapshot names the tile by while it sits in the plain grid.
    tile.dataset.type = type

    // The grid fallback, settled in a microtask: a layout that is replacing another mounts the
    // tile again right after the old one's unmount, so the grid only gets it if nobody did. With
    // a layout running, a tile nobody mounts is a closed window (its frame's × was clicked): it
    // stays out of the page rather than falling into the grid under the canvas.
    let disposed = false
    const settle = () => queueMicrotask(() => {
      if (!disposed && !tile.isConnected && !ctx.root.get('layout')) grid.append(tile)
    })
    ctx.effect(() => {
      settle()
      return () => {
        disposed = true
        tile.remove()
      }
    }, 'ui.tile()')
    this.windows.add(ctx, type, {
      title: header.textContent,
      open: 'once',
      singleton: true,
      mount(host, win) {
        host.append(tile)
        // The controls need the layout: they are drawn only while the tile is a window, with
        // their aria-labels and data-call (the layout's method each one stands for).
        const undraw = drawControls(controls, win)
        return () => {
          undraw()
          tile.remove()
          settle()
        }
      },
    })
    return body
  }

  snapshot(options?: UISnapshotOptions & { format?: 'text' }): string
  snapshot(options: UISnapshotOptions & { format: 'json' }): UISnapshotWindow[]
  snapshot(options: UISnapshotOptions = {}): string | UISnapshotWindow[] {
    return agent.snapshot(options)
  }

  act(ref: string, action: UIAction, value?: string, options?: UIActOptions & { format?: 'text' }): Promise<string>
  act(ref: string, action: UIAction, value: string | undefined, options: UIActOptions & { format: 'json' }): Promise<UISnapshotWindow | null>
  act(ref: string, action: UIAction, value?: string, options: UIActOptions & { format?: 'text' | 'json' } = {}): Promise<string | UISnapshotWindow | null> {
    return agent.act(ref, action, value, options)
  }
}

/** `ctx.plugins`: the plugin list, their fibers, on/off switches and reload from disk. */
class PluginHost extends Service implements PluginHostApi {
  declare scope: Context
  declare entries: Map<string, Entry>
  declare off: Set<string>
  /** Plugin name → unnamed controls warned about since it started (the panel's a11y badge). */
  declare unnamed: Map<string, number>
  /** Plugin name → its windows showing an agent nothing now (the same badge). */
  declare blinds: Map<string, number>

  constructor(ctx: Context) {
    super(ctx, 'plugins')
    // Methods are called through the service proxy with the caller's ctx; plugins must be
    // started from this one so they are owned by the host.
    this.scope = ctx
    this.entries = new Map()
    this.off = new Set(read())
    this.unnamed = new Map()
    this.blinds = new Map()
    ctx.on('internal/status', () => this.changed())
  }

  changed(): void {
    this.scope.emit('plugins/change')
  }

  /** The plugin in plugins.json that `fiber` belongs to: its own, or the one of an ancestor (a
   *  plugin's sub-plugin). null for the runtime's. */
  owner(fiber: Fiber): string | null {
    for (let f: Fiber | undefined = fiber; f && f.uid !== null && f.uid !== 0; ) {
      const uid = f.uid
      for (const entry of this.entries.values()) if (entry.fiber?.uid === uid) return entry.name
      const up: Fiber | undefined = f.parent?.fiber
      if (up === f) break
      f = up
    }
    return null
  }

  /** One more unnamed control in a window of `name`'s. */
  flag(name: string): void {
    this.unnamed.set(name, (this.unnamed.get(name) ?? 0) + 1)
    this.changed()
  }

  /** One window more (`delta` 1) or less (-1) of `name`'s that shows an agent nothing. */
  blind(name: string, delta: number): void {
    if (!this.entries.has(name)) return
    this.blinds.set(name, Math.max(0, (this.blinds.get(name) ?? 0) + delta))
    this.changed()
  }

  /** Rows for the panel: state plus the plugin's metadata (author, tags, provide, inject). */
  list(): PluginRow[] {
    return [...this.entries.values()].map(entry => {
      const plugin = entry.module?.default
      return {
        name: entry.name,
        author: plugin?.author ?? null,
        tags: [...(plugin?.tags ?? [])],
        provides: plugin?.provide ?? null,
        injects: injects(plugin),
        enabled: !this.off.has(entry.name),
        locked: !!plugin?.locked,
        version: plugin?.version ?? null,
        api: plugin?.api ?? null,
        state: entry.incompatible ? 'incompatible' : entry.error ? 'failed' : entry.fiber ? STATE[entry.fiber.state] : 'off',
        error: entry.error,
        loadedAt: entry.loadedAt,
        unnamed: this.unnamed.get(entry.name) ?? 0,
        blind: this.blinds.get(entry.name) ?? 0,
      }
    })
  }

  /** Reads plugins.json and adds, removes and (re)starts plugins to match it. */
  async sync(): Promise<string> {
    const response = await fetch(new URL('./plugins.json', import.meta.url), { cache: 'no-store' })
    if (!response.ok) throw new Error(`plugins.json: ${response.status}`)
    const names = pluginNames(await response.json())
    // Before importing React: the hook exists only in an explicitly enabled session.
    if (this.entries.size === 0 && names.includes('performance') && !this.off.has('performance')) {
      bootPerformance()
      performanceCollector?.instrumentEvents(this.scope, ctx => this.owner(ctx.fiber) ?? ctx.fiber.name ?? 'runtime')
    }
    const notes: string[] = []
    for (const [name, entry] of [...this.entries]) {
      if (names.includes(name)) continue
      await this.stop(entry)
      this.entries.delete(name)
      notes.push(`${name}: removed`)
    }
    for (const name of names) {
      if (this.entries.has(name)) continue
      this.entries.set(name, { name, module: null, fiber: null, error: null, incompatible: false, loadedAt: null })
      notes.push(await this.reload(name))
    }
    this.changed()
    return notes.join(', ') || 'plugins.json: no change'
  }

  /** Imports the plugin's file again and swaps the running instance for the new code. */
  async reload(name: string): Promise<string> {
    const entry = this.entries.get(name)
    if (!entry) return `${name}: not in plugins.json`
    const collector = performanceCollector
    const loadStarted = collector ? performance.now() : 0
    const loadKind = entry.module ? 'reload' : 'load'
    let module: unknown
    try {
      module = await import(new URL(`./plugins/${name}/index.js?v=${Date.now()}`, import.meta.url).href)
      if (!hasDefault(module)) throw new Error('the default export is not a plugin (a function, a class, or { apply })')
      // A plugin built by @tilr-dev/plugin/build may leave `version` and `api` to its build.
      stampBuild(module)
      collector?.event(loadKind, name, 'Import module', performance.now() - loadStarted)
    } catch (error) {
      collector?.event('error', name, 'Import failed', performance.now() - loadStarted)
      // The old instance keeps running; the panel shows why the new one did not start.
      entry.error = asError(error)
      entry.incompatible = false
      this.changed()
      return `${name}: import failed: ${entry.error.message}`
    }
    await this.stop(entry)
    entry.module = module
    entry.loadedAt = Date.now()
    await this.start(entry)
    // Import, stop and start (until start() returns; plugin.start times the apply). The first
    // import at boot goes through here too: that is a load, not a reload.
    if (collector) metric(`plugin.${loadKind}`, performance.now() - loadStarted, { plugin: name })
    return entry.incompatible ? `${name}: incompatible: ${entry.error?.message}` : `${name}: reloaded`
  }

  /** The running plugin (one with a fiber) that provides `service`, other than `except`. */
  provider(service: string, except?: Entry): Entry | undefined {
    for (const other of this.entries.values()) {
      if (other !== except && other.fiber && other.module?.default?.provide === service) return other
    }
  }

  /** Another running plugin that provides the same service (two themes at once). */
  rival(entry: Entry): Entry | undefined {
    const provide = entry.module?.default?.provide
    return provide ? this.provider(provide, entry) : undefined
  }

  /** Why `plugin` cannot run on this page, or null: its `api` range against the page's API, each
   *  `requires` range against the version of the provider running now. A service nobody
   *  provides yet is not checked here; `revalidate` checks it when its provider starts. */
  incompatibility(plugin: TilrPlugin): string | null {
    if (plugin.api !== undefined && !satisfies(__TILR_API__, plugin.api)) return `needs tilr api ${plugin.api}, the page has ${__TILR_API__}`
    for (const [service, range] of Object.entries(plugin.requires ?? {})) {
      const provider = this.provider(service)
      if (!provider || range === undefined) continue
      const version = provider.module?.default?.version
      if (version === undefined || !satisfies(version, range)) return `needs ${service} ${range}, ${provider.name} is ${version ?? 'unversioned'}`
    }
    return null
  }

  /** `entry`, a provider, just started: the plugins that require its service are checked
   *  against its version. A running one that no longer fits is stopped, an incompatible one
   *  gets another try (the provider may now be the right version). */
  async revalidate(entry: Entry): Promise<void> {
    const service = entry.module?.default?.provide
    if (!service) return
    for (const other of [...this.entries.values()]) {
      const plugin = other.module?.default
      // Object.keys, not `in`: a hand-written plugin's `requires` may be anything, and must not throw here.
      if (other === entry || !plugin || !Object.keys(plugin.requires ?? {}).includes(service)) continue
      if (other.incompatible) await this.start(other)
      else if (other.fiber) {
        const reason = this.incompatibility(plugin)
        if (reason) await this.refuse(other, reason)
      }
    }
  }

  /** Stops `entry` (if it runs) and marks it incompatible for `reason`. */
  async refuse(entry: Entry, reason: string): Promise<void> {
    await this.stop(entry)
    entry.error = new Error(reason)
    entry.incompatible = true
    this.changed()
  }

  async start(entry: Entry): Promise<void> {
    // No module: the file never imported, there is nothing to start (toggling such a plugin on).
    if (this.off.has(entry.name) || entry.fiber || !entry.module) return
    // One provider per service: a second one is switched off instead of failing on provide().
    if (this.rival(entry)) {
      this.off.add(entry.name)
      write([...this.off])
      this.changed()
      return
    }
    const plugin = entry.module.default
    const reason = this.incompatibility(plugin)
    if (reason) return this.refuse(entry, reason)
    entry.error = null
    entry.incompatible = false
    // A new instance draws new controls: its count starts over.
    this.unnamed.delete(entry.name)
    // Debug mode's timeline: the start, until the fiber's apply settles. No collector, no clock.
    const started = performanceCollector ? performance.now() : 0
    try {
      entry.fiber = this.scope.plugin(plugin)
    } catch (error) {
      // cordis rejects the plugin before a fiber exists (a shape it does not accept).
      entry.error = asError(error)
      this.changed()
      return
    }
    entry.fiber.await().then(() => {
      measure(`plugin:start ${entry.name}`, started)
      if (started) metric('plugin.start', performance.now() - started, { plugin: entry.name })
    }, (error: unknown) => {
      entry.error = asError(error)
      this.changed()
    })
    this.changed()
    await this.revalidate(entry)
  }

  async stop(entry: Entry): Promise<void> {
    const fiber = entry.fiber
    entry.fiber = null
    entry.error = null
    entry.incompatible = false
    if (fiber) {
      mark(`plugin:dispose ${entry.name}`)
      await fiber.dispose()
    }
    this.changed()
  }

  async toggle(name: string): Promise<void> {
    const entry = this.entries.get(name)
    if (!entry || entry.module?.default?.locked) return
    if (this.off.delete(name)) {
      // Switching a theme on switches the running one off: the service name is taken.
      const rival = this.rival(entry)
      if (rival) {
        this.off.add(rival.name)
        await this.stop(rival)
      }
      // Never imported (its file failed): try the file again, it may be fixed by now. An
      // incompatible plugin stays enabled, so its first toggle switches it off; this one checks
      // its versions again (the provider or the plugin may have been updated since).
      if (entry.module) await this.start(entry)
      else await this.reload(name)
    } else {
      this.off.add(name)
      await this.stop(entry)
    }
    write([...this.off])
  }
}

function read(): string[] {
  try {
    const names: unknown = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? 'null')
    return Array.isArray(names) ? names.filter((name): name is string => typeof name === 'string') : []
  } catch { return [] }
}

function write(names: string[]) {
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(names)) } catch {}
}

await root.plugin(Windows)
await root.plugin(UI)
await root.plugin(PluginHost)
// The class, not the PluginHost interface plugins see: hmr below reads `entries`.
const host = root.get('plugins') as PluginHost

// ---- the agent's surface: the snapshot and act (ctx.ui), the services, describe() -------------

/** The runtime's own services: always there, described with the page's API. */
const CORE = ['ui', 'plugins', 'windows']

/** The open windows: the layout's, else the tiles of the plain grid (named by their type). */
function frames(): Frame[] {
  const layout = root.get('layout')
  if (layout) {
    const windows = root.get('windows') as Windows
    return layout.list().map(row => {
      // The content and the adapter: while the window's type has it mounted.
      const mounted = windows.mounted(row.id)
      const agent = mounted && mounted.type === row.type ? windows.get(row.type)?.agent : undefined
      return {
        id: row.id, type: row.type, title: row.title, mode: row.mode, focused: row.focused,
        ...(row.parent ? { parent: row.parent } : {}),
        host: document.querySelector(`.window[data-window="${CSS.escape(row.id)}"]`),
        ...(mounted ? { content: mounted.host, handle: mounted.win } : {}),
        ...(agent ? { agent } : {}),
      }
    })
  }
  return Array.from(document.querySelectorAll<HTMLElement>('#grid > .tile[data-type]'), tile => {
    const type = tile.dataset.type ?? ''
    return { id: type, type, title: tile.querySelector('header')?.textContent ?? type, mode: 'tile' as const, focused: false, host: tile }
  })
}

/** The window an element is in and the plugin that registered its type. */
function ownerOf(el: Element): Owner | null {
  const win = closest(el, '.window[data-window]')
  const tile = win ? null : closest(el, '.tile[data-type]')
  const type = win?.getAttribute('data-type') ?? tile?.getAttribute('data-type')
  if (!type) return null
  const windows = root.get('windows') as Windows
  return { window: win?.getAttribute('data-window') ?? type, plugin: windows.owner(type) ?? type }
}

const agent = new Agent(frames, ownerOf)
// The engine's promise: every control is in the snapshot, named or not. The warning (and the
// panel's badge) is how a plugin learns that an agent sees one of its controls as "".
agent.watch((owner, el) => {
  console.warn(`[tilr] ${owner.plugin}: unnamed ${describeElement(el)} in window ${owner.window}: give it text, aria-label or a <label>`)
  if (host.entries.has(owner.plugin)) host.flag(owner.plugin)
})

/** The services running now: the runtime's and every running plugin's `provide`. */
function running(): string[] {
  const names = new Set(CORE)
  for (const entry of host.entries.values()) {
    const provide = entry.fiber ? entry.module?.default?.provide : undefined
    if (provide && root.get(provide) != null) names.add(provide)
  }
  return [...names]
}

/** A declarations file of the site, or null (none, or unreadable). */
async function declarations(path: string): Promise<string | null> {
  try {
    const response = await fetch(new URL(path, import.meta.url), { cache: 'no-store' })
    return response.ok ? await response.text() : null
  } catch { return null }
}

/** The services the page's API declares (the members of `export interface TilrServices`). */
function pageServices(api: string): string[] {
  const start = api.indexOf('export interface TilrServices {')
  if (start === -1) return []
  const body = api.slice(start, api.indexOf('\n}', start))
  return [...body.matchAll(/^\s+(\w+): /gm)].map(match => match[1])
}

async function describe(service?: string): Promise<ServiceDescription[]> {
  const names = service === undefined ? running() : [service]
  // The declarations, fetched once per call: every service is marked against its contract.
  const texts = new Map<string, Promise<string | null>>()
  const load = (path: string): Promise<string | null> => {
    let text = texts.get(path)
    if (!text) texts.set(path, text = declarations(path))
    return text
  }
  return Promise.all(names.map(async name => {
    const target = root.get(name) as object | null | undefined
    if (target == null) throw new Error(`no service "${name}" is running`)
    const core = CORE.includes(name)
    const provider = core ? undefined : host.provider(name)
    const plugin = core ? 'runtime' : provider?.name ?? null
    const version = core ? __TILR_API__ : provider?.module?.default?.version ?? null
    // The page's API declares the runtime's services and the core plugins' (layout, store …);
    // any other is declared by its plugin, in plugins/<name>/api.d.ts (a 404 when it has none,
    // which WebKit logs).
    const page = await load('./api.d.ts')
    let api: string | null = null
    if (page && (core || pageServices(page).includes(name))) api = page
    else if (plugin && !core) api = await load(`./plugins/${plugin}/api.d.ts`)
    const contract = api === null ? null : contractOf(api, name)
    return {
      name, plugin, version, ...members(target, Service.prototype, contract),
      // A service with a `Service.invoke` body is a function: `$.open(target)`.
      ...(typeof target === 'function' ? { callable: true as const } : {}),
      api: service === undefined ? null : api,
    }
  }))
}

// Called by the native app (main.swift) with paths relative to the site folder. The return
// value lands in the app's stdout. Anything else than plugins/… reloads the whole page there.
window.tilr = {
  root,
  api: __TILR_API__,
  react: reactMode,
  services: serviceProxy(name => root.get(name) ?? undefined, running) as TilrGlobal['services'],
  describe,
  hmr: {
    async changed(paths: string[]) {
      const names = new Set<string>()
      let manifest = false
      for (const path of paths) {
        if (path === 'plugins.json') manifest = true
        const match = /^plugins\/([^/]+)\//.exec(path)
        if (match) names.add(match[1])
      }
      const notes: string[] = []
      const started = Date.now()
      if (manifest) notes.push(await host.sync())
      for (const name of names) {
        // A plugin that sync() just added was imported from disk a moment ago.
        if ((host.entries.get(name)?.loadedAt ?? 0) >= started) continue
        notes.push(await host.reload(name))
      }
      return notes.join('; ')
    },
  },
}

console.log(await host.sync())
mark('page:ready')
